//! Skill readiness -> committed integer projectile -> actual shield/health ->
//! ordered IC feedback. A dead (still present) owner does not retract the shot.
use infinite_core::*;use std::num::{NonZeroU16,NonZeroU32};
fn n(v:u32)->NonZeroU32{NonZeroU32::new(v).unwrap()}fn p(x:i32)->GridPosition{GridPosition{x,y:0}}
fn main(){
 let mut w=World::default();let owner=w.spawn(p(0)).unwrap();w.configure_health(owner,100,n(100)).unwrap();w.configure_resource(owner,40,40).unwrap();let targets=[20,40,60].map(|x|{let e=w.spawn(p(x)).unwrap();w.configure_health(e,100,n(100)).unwrap();e});w.grant_shield(ShieldSpec{source:owner,target:targets[0],duration:None,profile:ShieldProfile::Absorb{capacity:n(15)}}).unwrap();
 w.learn_skill(owner,SkillSpec{id:SkillId(1),resource_cost:20,cooldown_ticks:6,windup_ticks:2,recovery:None,ingress_grace_ticks:0}).unwrap();w.start_cast(CastRequest{caster:owner,request_id:1,skill:SkillId(1),target:CastTarget::Point(p(80))}).unwrap();
 let mut projectiles=Projectiles::new(n(32));let mut skills=Vec::new();let mut ends=Vec::new();let mut frame=CombatFrame::new(n(32));let mut sender=CombatSyncSender::new_shielded(1,CombatSyncConfig::default()).unwrap();let mut client=CombatReplica::new(1);let mut feedback=Vec::new();let mut launched=0;
 for _ in 0..6{w.advance_tick().unwrap();w.resolve_casts(16,&mut skills).unwrap();for event in &skills{if let SkillEvent::Ready(ready)=event{assert_eq!(ready.request.caster,owner);let cast=projectiles.create_cast(&w,owner,NonZeroU16::new(1).unwrap(),3).unwrap();projectiles.launch(&w,ProjectileLaunch{cast,from:p(0),to:p(80),activate_at:w.tick(),travel_ticks:NonZeroU16::new(4).unwrap(),radius:0,max_hits:NonZeroU16::new(3).unwrap(),damage:n(10),strict_ends:false,require_sight:false}).unwrap();projectiles.seal_cast(cast).unwrap();launched+=1;}}
  if w.tick()==Tick(3){w.apply_damage(owner,100).unwrap();}let mut events=Vec::new();projectiles.begin(&mut w).unwrap().step(16,&mut CombatQueryBudget::new(10000),&mut events,4096,&mut ends,|_,impact|Some(n(impact.base_damage.get()*u32::from(impact.ordinal+1)))).unwrap();frame.capture(&w,&events).unwrap();sender.observe(&frame,ViewRect{min:GridPosition{x:-16,y:-16},max:GridPosition{x:96,y:16}}).unwrap();if let Some(packet)=sender.prepare().unwrap(){let report=client.apply(packet).unwrap();feedback.extend(client.drain_feedback());sender.acknowledge_packet(&report.acknowledgement()).unwrap();}
 }
 assert_eq!(launched,1);assert_eq!(feedback.len(),3);assert_eq!(feedback.iter().map(|e|(e.tick.0,e.target,e.kind)).collect::<Vec<_>>(),vec![(2,targets[0],CombatFeedbackKind::Hit{damage:0,remaining:100}),(3,targets[1],CombatFeedbackKind::Hit{damage:20,remaining:80}),(4,targets[2],CombatFeedbackKind::Hit{damage:30,remaining:70})]);for (target,hp)in targets.into_iter().zip([100,80,70]){assert_eq!(w.health(target).unwrap().current,hp);assert_eq!(client.states().iter().find(|s|s.entity==target).unwrap().health.unwrap().current,hp);}assert_eq!(w.resource(owner).unwrap().current,20);assert!(projectiles.is_empty());assert_eq!(projectiles.casts(),0);assert_eq!(ends.len(),1);println!("skill_ready=1 projectiles=1 ordered_hits=3 ticks=[2,3,4] hp=[100,80,70] owner_hp=0 resource=20 shield_absorbed=10 client_matches=true");
}
